Better: restructure script to have top-level definitions: state variables, maybe config constants later. For now we can just extend script.

Our script currently:

<script>
  // === STATE ==============================================================
  let player = { x: 400, y: 300, radius: 5 };
  let hazards = [];
  let score = 0;
  let phase = "menu";
  (() => {
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    // Fill initial background
    ctx.fillStyle = '#05050c';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const restartBtn = document.getElementById('restart');
    restartBtn.addEventListener('click', () => {
      console.log('Restart clicked');
    });

    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'r' || ev.key === 'R') {
        console.log('Restart key pressed');
      }
      // Prevent default scrolling for space
      if (ev.key === ' ') ev.preventDefault();
    });
  })();
</script>

